// Preflight. Every check here maps to a promise in the statement of work, and each
// one fails the run loudly rather than warning into a log nobody reads.
const MONTHLY_TARGET = Number($env.MONTHLY_TARGET || 14000);
const WORKING_DAYS = Number($env.WORKING_DAYS_PER_MONTH || 22);
const SLOTS = Number($env.SEND_SLOTS_PER_DAY || 9);
const PER_MAILBOX = Number($env.PER_MAILBOX_DAILY_CAP || 35);
const domainsVerified = String($env.SENDING_DOMAINS_VERIFIED || 'false').toLowerCase() === 'true';
const mode = String($env.APPROVAL_MODE || 'review').toLowerCase();
const ramp = Number($env.RAMP_DAY || 999);

if (!domainsVerified) {
  throw new Error('SENDING_DOMAINS_VERIFIED is not true. Every sending domain needs SPF, DKIM and DMARC confirmed and warmup finished before this runs. None of them may be the client primary domain.');
}

if (['review', 'auto'].indexOf(mode) === -1) {
  throw new Error('APPROVAL_MODE must be "review" or "auto", got: ' + mode);
}

// Ramp: week 1 at 25%, week 2 at 50%, week 3 at 75%, full from week 4.
// Going to full volume on a fresh set of mailboxes is the single fastest way to burn them.
let rampFactor = 1;
if (ramp <= 5) rampFactor = 0.25;
else if (ramp <= 10) rampFactor = 0.5;
else if (ramp <= 15) rampFactor = 0.75;

const dailyTarget = Math.round((MONTHLY_TARGET / WORKING_DAYS) * rampFactor);
const hourlyTarget = Math.ceil(dailyTarget / SLOTS);
const mailboxesNeeded = Math.ceil(dailyTarget / PER_MAILBOX);

// Ramadan and Eid: response rates collapse and sending through it looks tone deaf.
const paused = String($env.SEASONAL_PAUSE || 'false').toLowerCase() === 'true';
if (paused) {
  return [{ json: { paused: true, reason: String($env.SEASONAL_PAUSE_REASON || 'seasonal pause is on') } }];
}

return [{ json: {
  paused: false,
  monthly_target: MONTHLY_TARGET,
  daily_target: dailyTarget,
  hourly_target: hourlyTarget,
  ramp_day: ramp,
  ramp_factor: rampFactor,
  per_mailbox_cap: PER_MAILBOX,
  mailboxes_needed: mailboxesNeeded,
  mode: mode,
  day_key: new Date().toISOString().slice(0, 10),
  month_key: new Date().toISOString().slice(0, 7),
  year_key: new Date().toISOString().slice(0, 4)
}}];

// THE ALLOCATOR. Three independent ceilings have to hold at once, and this is the
// only node that knows about all three:
//
//   1. STATUTE      - per SUBJECT LINE, not per campaign. Singapore's Spam Control Act
//                     calls it bulk above 100 same-subject in 24h, 1,000 in 30 days or
//                     10,000 in a year. At 14k/month that needs 17+ rotating subjects.
//   2. DELIVERABILITY - per MAILBOX. 30-40 a day each, or reputation goes.
//   3. TARGET       - the monthly number in the contract, spread over working days
//                     and hourly slots, scaled by the warmup ramp.
//
// Whichever ceiling binds first wins, and the reason is recorded either way.
const cfg = $('preflight and ramp').first().json;
const leads = $('[cred] Sheets - read leads').all().map((i) => i.json);
const mailboxes = $('[cred] Sheets - read mailboxes').all().map((i) => i.json);
const ledger = $input.all().map((i) => i.json);

const MIN_CONFIDENCE = Number($env.MIN_CONFIDENCE || 70);
const SUBJ_DAY = Number($env.SUBJECT_CAP_24H || 90);
const SUBJ_MONTH = Number($env.SUBJECT_CAP_30D || 900);
const SUBJ_YEAR = Number($env.SUBJECT_CAP_YEAR || 9000);

// --- sequences and their subject variants -------------------------------------
let sequences;
try {
  sequences = JSON.parse($env.SEQUENCES_JSON || '[]');
} catch (e) {
  throw new Error('SEQUENCES_JSON is not valid JSON: ' + String(e.message));
}
if (!sequences.length) throw new Error('SEQUENCES_JSON is empty. Define 3-5 sequences, each with subject variants.');

const subjects = [];
for (const seq of sequences) {
  for (const s of (seq.subjects || [])) {
    subjects.push({ subject_id: seq.id + '::' + s.replace(/[^a-zA-Z0-9]+/g, '-').slice(0, 40), subject: s, sequence: seq.id, angle: seq.angle || '' });
  }
}

// The annual ceiling is the binding one at this volume - check it before sending, not after.
const needed = Math.ceil((cfg.monthly_target * 12) / SUBJ_YEAR);
if (subjects.length < needed) {
  throw new Error('Only ' + subjects.length + ' subject variants defined. At ' + cfg.monthly_target + '/month you need at least ' + needed + ' to stay under the per-subject annual threshold. Add variants to SEQUENCES_JSON.');
}

// --- current counters ---------------------------------------------------------
const subjState = {};
for (const s of subjects) subjState[s.subject_id] = { sent_today: 0, sent_month: 0, sent_year: 0 };
for (const row of ledger) {
  const id = String(row.subject_id || '');
  if (!subjState[id]) continue;
  subjState[id] = {
    sent_today: String(row.day_key) === cfg.day_key ? Number(row.sent_today || 0) : 0,
    sent_month: String(row.month_key) === cfg.month_key ? Number(row.sent_month || 0) : 0,
    sent_year: String(row.year_key) === cfg.year_key ? Number(row.sent_year || 0) : 0
  };
}

const boxes = mailboxes
  .filter((m) => String(m.active).toLowerCase() === 'true' && String(m.warmed).toLowerCase() === 'true')
  .map((m) => ({
    email: m.mailbox_email,
    domain: m.domain,
    cap: Number(m.daily_cap || cfg.per_mailbox_cap),
    sent_today: String(m.day_key) === cfg.day_key ? Number(m.sent_today || 0) : 0
  }));

if (!boxes.length) throw new Error('No warmed, active mailbox in the Mailboxes tab.');

const mailboxCapacity = boxes.reduce((t, b) => t + Math.max(0, b.cap - b.sent_today), 0);
if (boxes.length < cfg.mailboxes_needed) {
  // Not fatal - it just means today's target is unreachable, and saying so beats
  // quietly sending less and letting someone discover the shortfall at month end.
  cfg.mailbox_shortfall = cfg.mailboxes_needed - boxes.length;
}

// --- eligible leads -----------------------------------------------------------
const suppressedEmails = new Set();
const suppressedDomains = new Set();
for (const item of $('[cred] Sheets - read suppression').all()) {
  const e = String(item.json.email || '').toLowerCase().trim();
  const d = String(item.json.domain || '').toLowerCase().trim();
  if (e) suppressedEmails.add(e);
  if (d) suppressedDomains.add(d);
}

const dropped = { no_email: 0, suppressed: 0, already_contacted: 0, low_confidence: 0, held_by_cap: 0, no_subject_headroom: 0, no_mailbox_headroom: 0 };
const eligible = [];

for (const lead of leads) {
  const email = String(lead.email || '').toLowerCase().trim();
  const stage = String(lead.stage || '').toLowerCase();
  if (!email) { dropped.no_email++; continue; }
  if (suppressedEmails.has(email) || suppressedDomains.has(String(lead.domain || '').toLowerCase())) { dropped.suppressed++; continue; }
  if (['queued', 'sent', 'replied', 'booked', 'suppressed'].indexOf(stage) !== -1) { dropped.already_contacted++; continue; }
  if (Number(lead.confidence || 0) < MIN_CONFIDENCE) { dropped.low_confidence++; continue; }
  eligible.push(lead);
}

eligible.sort((a, b) => Number(b.fit_score || 0) - Number(a.fit_score || 0));

// --- allocate -----------------------------------------------------------------
const hourly = Math.min(cfg.hourly_target, mailboxCapacity);
const out = [];
let boxIndex = 0;

for (const lead of eligible) {
  if (out.length >= hourly) { dropped.held_by_cap++; continue; }

  // Sticky sequence per lead, so a lead never jumps between angles mid-cadence.
  const hash = String(lead.lead_id || lead.email).split('').reduce((h, c) => ((h * 31) + c.charCodeAt(0)) % 100000, 7);
  const seqIndex = hash % sequences.length;
  const seq = sequences[seqIndex];
  const seqSubjects = subjects.filter((s) => s.sequence === seq.id);

  // Cheapest subject first: the one furthest from its ceilings.
  const usable = seqSubjects
    .filter((s) => {
      const st = subjState[s.subject_id];
      return st.sent_today < SUBJ_DAY && st.sent_month < SUBJ_MONTH && st.sent_year < SUBJ_YEAR;
    })
    .sort((a, b) => subjState[a.subject_id].sent_today - subjState[b.subject_id].sent_today);

  if (!usable.length) { dropped.no_subject_headroom++; continue; }
  const chosen = usable[0];

  // Round-robin the mailboxes, skipping any at its daily cap.
  let box = null;
  for (let tries = 0; tries < boxes.length; tries++) {
    const candidate = boxes[(boxIndex + tries) % boxes.length];
    if (candidate.sent_today < candidate.cap) { box = candidate; boxIndex = (boxIndex + tries + 1) % boxes.length; break; }
  }
  if (!box) { dropped.no_mailbox_headroom++; continue; }

  subjState[chosen.subject_id].sent_today++;
  subjState[chosen.subject_id].sent_month++;
  subjState[chosen.subject_id].sent_year++;
  box.sent_today++;

  out.push({ json: Object.assign({}, lead, {
    sequence_id: seq.id,
    sequence_angle: seq.angle || '',
    sequence_step: Number(lead.sequence_step || 0),
    ab_variant: (hash % 2 === 0) ? 'A' : 'B',
    subject_id: chosen.subject_id,
    subject_template: chosen.subject,
    mailbox: box.email,
    mailbox_domain: box.domain,
    slot_at: new Date().toISOString(),
    day_key: cfg.day_key,
    month_key: cfg.month_key,
    year_key: cfg.year_key,
    approval_mode: cfg.mode,
    run_stats: {
      hourly_target: cfg.hourly_target,
      daily_target: cfg.daily_target,
      ramp_factor: cfg.ramp_factor,
      mailbox_capacity_left: mailboxCapacity,
      mailbox_shortfall: cfg.mailbox_shortfall || 0,
      subject_variants: subjects.length,
      eligible: eligible.length,
      dropped: dropped
    }
  })});
}

return out;

// Assemble. The unsubscribe line is appended here, not left to the sending tool, so
// it survives anyone reconfiguring the campaign later.
const leads = $('allocate subjects and mailboxes').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const lead = Object.assign({}, leads[i].json);
  const res = $input.all()[i].json || {};
  const body = String(((((res.choices || [])[0]) || {}).message || {}).content || '').trim();

  if (!body) {
    const why = ((((res.choices || [])[0]) || {}).finish_reason) || (res.error && res.error.message) || 'none';
    throw new Error('Empty draft for ' + lead.lead_id + ' (finish_reason: ' + why + ')');
  }

  const words = body.split(' ').filter(Boolean).length;
  const subject = String(lead.subject_template)
    .split('{company}').join(lead.company || 'your team')
    .split('{first_name}').join(lead.first_name || 'there');

  const unsubscribe = '\n\n--\n' + ($env.SENDER_SIGNATURE || 'Sent by a person, not a list.') +
    '\nNot relevant? Reply "stop" and I will not contact you again.';

  out.push({ json: Object.assign({}, lead, {
    subject: subject,
    body: body + unsubscribe,
    word_count: words,
    needs_human_look: words > 110 || body.toLowerCase().indexOf('i hope this') !== -1 || body.indexOf('Mr.') !== -1 || body.indexOf('Mrs.') !== -1,
    drafted_at: new Date().toISOString()
  })});
}

return out;

// Roll the counters forward. This runs whether the emails were queued or parked,
// because a parked draft still consumed a subject slot the moment it was written -
// double-counting is safer here than under-counting against a statutory ceiling.
const cfg = $('preflight and ramp').first().json;
const sent = $('assemble message').all().map((i) => i.json);
const prior = {};

for (const item of $('[cred] Sheets - read send ledger').all()) {
  const r = item.json;
  if (!r.subject_id) continue;
  prior[r.subject_id] = r;
}

const bump = {};
for (const s of sent) {
  if (!bump[s.subject_id]) bump[s.subject_id] = { subject: s.subject_template, n: 0 };
  bump[s.subject_id].n++;
}

return Object.keys(bump).map((id) => {
  const p = prior[id] || {};
  const sameDay = String(p.day_key) === cfg.day_key;
  const sameMonth = String(p.month_key) === cfg.month_key;
  const sameYear = String(p.year_key) === cfg.year_key;

  return { json: {
    subject_id: id,
    subject: bump[id].subject,
    day_key: cfg.day_key,
    sent_today: (sameDay ? Number(p.sent_today || 0) : 0) + bump[id].n,
    month_key: cfg.month_key,
    sent_month: (sameMonth ? Number(p.sent_month || 0) : 0) + bump[id].n,
    year_key: cfg.year_key,
    sent_year: (sameYear ? Number(p.sent_year || 0) : 0) + bump[id].n,
    last_sent: new Date().toISOString()
  }};
});

// Mailbox counters, same rollover logic.
const cfg = $('preflight and ramp').first().json;
const sent = $('assemble message').all().map((i) => i.json);
const prior = {};
for (const item of $('[cred] Sheets - read mailboxes').all()) {
  const r = item.json;
  if (r.mailbox_email) prior[r.mailbox_email] = r;
}

const bump = {};
for (const s of sent) bump[s.mailbox] = (bump[s.mailbox] || 0) + 1;

return Object.keys(bump).map((mb) => {
  const p = prior[mb] || {};
  const sameDay = String(p.day_key) === cfg.day_key;
  return { json: {
    mailbox_email: mb,
    domain: p.domain || '',
    daily_cap: p.daily_cap || cfg.per_mailbox_cap,
    warmed: p.warmed || 'true',
    active: p.active || 'true',
    day_key: cfg.day_key,
    sent_today: (sameDay ? Number(p.sent_today || 0) : 0) + bump[mb]
  }};
});

// Mark what we touched, so the next slot cannot pick the same lead up again.
return $('assemble message').all().map((item) => ({ json: {
  lead_id: item.json.lead_id,
  email: item.json.email,
  stage: 'queued',
  sequence_id: item.json.sequence_id,
  sequence_step: Number(item.json.sequence_step || 0) + 1,
  ab_variant: item.json.ab_variant,
  subject_id: item.json.subject_id,
  mailbox: item.json.mailbox,
  queued_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
}}));

// Post only when something needs a decision. Nine slots a day of 'all good' is how
// a channel gets muted, and a muted channel hides the slot that mattered.
const sent = $('assemble message').all();
if (!sent.length) return [];

const first = sent[0].json;
const st = first.run_stats || {};
const d = st.dropped || {};
const mode = first.approval_mode === 'auto' ? 'queued' : 'parked for review';

const problems = [];
if (st.mailbox_shortfall) problems.push(':warning: *' + st.mailbox_shortfall + ' mailboxes short* of the daily target. Add mailboxes or the monthly number will not land.');
if (d.no_subject_headroom) problems.push(':warning: ' + d.no_subject_headroom + ' leads held: every subject in their sequence is at a statutory ceiling. Add subject variants.');
if (d.no_mailbox_headroom) problems.push(':warning: ' + d.no_mailbox_headroom + ' leads held: every mailbox is at its daily cap.');
if (sent.filter((s) => s.json.needs_human_look).length) problems.push(':mag: ' + sent.filter((s) => s.json.needs_human_look).length + ' drafts flagged for a human look.');

if (!problems.length && String($env.QUIET_SLOTS || 'true') === 'true') return [];

const lines = [
  ':outbox_tray: *Outbound slot* - ' + sent.length + ' ' + mode + ' (hourly target ' + st.hourly_target + ', daily ' + st.daily_target + ' at ramp ' + Math.round((st.ramp_factor || 1) * 100) + '%)',
  '_' + st.subject_variants + ' subject variants live, ' + st.eligible + ' leads eligible._'
];
problems.forEach((p) => lines.push(p));
lines.push('_Skipped: ' + (d.already_contacted || 0) + ' already contacted, ' + (d.suppressed || 0) + ' suppressed, ' + (d.low_confidence || 0) + ' low confidence, ' + (d.held_by_cap || 0) + ' held for a later slot._');

return [{ json: { text: lines.join('\n') } }];
